//! 🔔️ The genuine receiving source acknowledges and rearms without replacing its paid frame or lifetime stock.
use semio_framework_job_context::*;
use semio_framework_job_testing_caller::OriginalJobFixtureCaller;
use semio_framework_trace::observe_heap_allocations_on_this_thread as observe;
#[global_allocator]
static ACK_HEAP:semio_framework_trace::HeapWitness=semio_framework_trace::HeapWitness;
#[test]
fn original_receiver_acknowledges_then_removes_each_descriptor_before_same_source_rearm(){
 let law:serde_json::Value=serde_json::from_str(include_str!("../case.json")).unwrap();let schema:serde_json::Value=serde_json::from_str(include_str!("../case.schema.json")).unwrap();for(k,v)in law.as_object().unwrap(){assert_eq!(&schema["properties"][k]["const"],v);}let s=&law["source"];let stock=RetainedCloneGrant{maximum_items:s["items"].as_u64().unwrap()as usize,maximum_copy_bytes:s["copyBytes"].as_u64().unwrap()as usize,maximum_capacity_bytes:s["capacityBytes"].as_u64().unwrap()as usize,maximum_release_bytes:s["releaseBytes"].as_u64().unwrap()as usize,maximum_depth:s["depth"].as_u64().unwrap()as usize};let q=RetainedCloneGrant{maximum_items:1,..stock};let mut caller=OriginalJobFixtureCaller::admit(OperationId(7630),Generation(1),stock,||Some(0),s["deadlineUs"].as_u64().unwrap(),s["fuel"].as_u64().unwrap());let mut origin=OriginalJobReturnOrigin::empty();let source=caller.turn(q,|cx|Ok(cx.original_source_parent()?.source_identity()?)).unwrap();
 for sequence in 0..law["outcomes"].as_u64().unwrap(){
  let mut ready=false;for _ in 0..law["maximumTurns"].as_u64().unwrap(){caller.turn(q,|cx|cx.with_original_work_loan(1,cx.original_absolute_deadline_us(),|cx|{let(result,heap)=observe(||origin.admit(cx));ready=result?;assert!(!heap.overflowed);if sequence!=0{assert_eq!(heap.requested_bytes,0);}Ok(())})).unwrap();if ready{break}}assert!(ready);let mut pending=None;
  caller.turn(q,|cx|cx.with_original_work_loan(1,cx.original_absolute_deadline_us(),|cx|{let claim=origin.enter_body(cx)?.unwrap();let result=JobOutcomeBorrow::admit_yield(cx).map_err(OriginalTurnFailure::from);match claim.finish(cx,InteractiveJobStep::from_callback(result),None){OriginalJobReturn::Outcome(outcome)=>pending=Some(outcome.into_descriptor()),_=>panic!("actual yielded descriptor")};assert!(origin.receive_outcome(cx,&mut pending)?);Ok(())})).unwrap();assert!(pending.is_none());assert_eq!(origin.outcome().unwrap().kind(),JobOutcomeKind::Yield);
  caller.turn(RetainedCloneGrant{maximum_items:0,..q},|cx|{let p=cx.retained_progress();let work=cx.original_work_units_spent();let(result,heap)=observe(||origin.acknowledge_outcome(cx));assert!(!result?);assert!(!origin.outcome().unwrap().is_acknowledged());assert_eq!(cx.retained_progress(),p);assert_eq!(cx.original_work_units_spent(),work);assert!(!heap.overflowed);assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));Ok(())}).unwrap();
  for turn in 0..2{caller.turn(q,|cx|cx.with_original_work_loan(1,cx.original_absolute_deadline_us(),|cx|{let work=cx.original_work_units_spent();let(result,heap)=observe(||origin.acknowledge_outcome(cx));assert_eq!(result?,turn==1);assert_eq!(cx.original_work_units_spent()-work,1);assert!(!heap.overflowed);assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));if turn==0{assert!(origin.outcome().unwrap().is_acknowledged());}assert_eq!(cx.original_source_parent()?.source_identity()?,source);Ok(())})).unwrap();}
  caller.turn(q,|cx|{let work=cx.original_work_units_spent();assert!(origin.acknowledge_outcome(cx)?);assert_eq!(cx.original_work_units_spent(),work);Ok(())}).unwrap();assert!(origin.outcome().is_none());
 }
 for _ in 0..law["maximumTurns"].as_u64().unwrap(){if origin.terminal_is_empty(){break}caller.turn(q,|cx|origin.close_step(cx).map(|_|())).unwrap();}assert!(origin.terminal_is_empty());let(_,heap)=observe(||drop(origin));assert!(!heap.overflowed);assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));caller.retire(stock);
}
